CREATE TABLE IF NOT EXISTS online_presence (user_id INTEGER PRIMARY KEY, seen_at INTEGER NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS multiplayer_rooms (id INTEGER PRIMARY KEY AUTO_INCREMENT, token_hash VARCHAR(64) NOT NULL UNIQUE, host_id INTEGER NOT NULL, guest_id INTEGER, invited_id INTEGER, host_deck INTEGER NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'waiting', state_json TEXT, version INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, FOREIGN KEY (host_id) REFERENCES users(id), FOREIGN KEY (guest_id) REFERENCES users(id), FOREIGN KEY (invited_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS multiplayer_invites (id INTEGER PRIMARY KEY AUTO_INCREMENT, room_id INTEGER NOT NULL, sender_id INTEGER NOT NULL, recipient_id INTEGER NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'pending', created_at INTEGER NOT NULL, FOREIGN KEY (room_id) REFERENCES multiplayer_rooms(id), FOREIGN KEY (sender_id) REFERENCES users(id), FOREIGN KEY (recipient_id) REFERENCES users(id));
